"use client";

import type { Variants } from "motion/react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import type { ElementType } from "react";
import { useEffect, useState } from "react";

import { EASE_OUT } from "@/lib/ease";
import { cn } from "@/lib/utils";

interface MorphingTextProps {
  words: string[];
  interval?: number;
  pauseOnHover?: boolean;
  as?: ElementType;
  className?: string;
}

const morphVariants: Variants = {
  animate: {
    filter: "blur(0px)",
    opacity: 1,
    transition: { duration: 0.4, ease: EASE_OUT },
    y: 0,
  },
  exit: {
    filter: "blur(6px)",
    opacity: 0,
    transition: { duration: 0.18, ease: EASE_OUT },
    y: -10,
  },
  initial: { filter: "blur(6px)", opacity: 0, y: 10 },
};

const reducedVariants: Variants = {
  animate: {
    opacity: 1,
    transition: { duration: 0.15, ease: EASE_OUT },
  },
  exit: { opacity: 0, transition: { duration: 0.1, ease: EASE_OUT } },
  initial: { opacity: 0 },
};

const MorphingText = ({
  words,
  interval = 3000,
  pauseOnHover = false,
  as: Tag = "div",
  className,
  ...props
}: MorphingTextProps & React.HTMLAttributes<HTMLElement>) => {
  const [index, setIndex] = useState(0);
  const [paused, setPaused] = useState(false);
  const reduce = useReducedMotion();

  useEffect(() => {
    if (paused || words.length <= 1) {
      return;
    }

    const id = setInterval(() => {
      setIndex((prev) => (prev + 1) % words.length);
    }, interval);

    return () => clearInterval(id);
  }, [interval, paused, words.length]);

  return (
    <Tag
      className={cn("inline-flex overflow-hidden", className)}
      onMouseEnter={() => pauseOnHover && setPaused(true)}
      onMouseLeave={() => pauseOnHover && setPaused(false)}
      {...props}
    >
      <AnimatePresence mode="wait" initial={false}>
        <motion.span
          key={words[index]}
          variants={reduce ? reducedVariants : morphVariants}
          initial="initial"
          animate="animate"
          exit="exit"
          className="inline-block"
        >
          {words[index]}
        </motion.span>
      </AnimatePresence>
    </Tag>
  );
};

export default MorphingText;

// Shared motion tokens. Easing curves mirror the CSS custom properties in
// globals.css; springs are the canonical physics used across components.
// Strong custom variants — defaults like `ease-in`/`ease-out` feel weak.

export const EASE_OUT = [0.16, 1, 0.3, 1] as const;
export const EASE_IN_OUT = [0.77, 0, 0.175, 1] as const;
export const EASE_DRAWER = [0.32, 0.72, 0, 1] as const;

/** CSS string form of EASE_OUT for inline style transitions. */
export const EASE_OUT_CSS = "cubic-bezier(0.16, 1, 0.3, 1)";

/** Press feedback on buttons and other tappable surfaces. */
export const SPRING_PRESS = {
  damping: 30,
  mass: 0.6,
  stiffness: 500,
  type: "spring",
} as const;

/** Content swaps — label/icon slots trading places inside a control. */
export const SPRING_SWAP = {
  damping: 30,
  mass: 0.55,
  stiffness: 460,
  type: "spring",
} as const;

/** Overlay panel entrances — modals and sheets summoned by pointer. */
export const SPRING_PANEL = {
  damping: 40,
  mass: 0.5,
  stiffness: 420,
  type: "spring",
} as const;

/** Shared-layout glides — pills, indicators and panels morphing between positions. */
export const SPRING_LAYOUT = {
  damping: 32,
  mass: 0.6,
  stiffness: 360,
  type: "spring",
} as const;

/** Cursor-follow physics for decorative mouse tracking (magnetic, tilt, dock). */
export const SPRING_MOUSE = {
  damping: 20,
  mass: 0.5,
  stiffness: 280,
} as const;
